const cloudModules=['foundation','compute','network','native','sre'];
const aiModules=['training','platform','practice'];
function chapterLink(a){return `<a class="chapter-row" href="${articleURL(a.id)}"><div class="chapter-top"><span>CHAPTER ${a.number}</span><span>${a.level} · ${progress[a.id]?'已读 ✓':'开始阅读 ↗'}</span></div><h2>${a.title}</h2><p>${a.desc}</p></a>`}
function learningContract(a){if(!a.objectives)return '<div class="evidence-note">内容类型：基础导读 · 用于建立概念，配套实战见实验室。</div>';return `<div class="learning-contract"><div><strong>本章你将掌握</strong><ul>${a.objectives.map(t=>'<li>'+t+'</li>').join('')}</ul></div><p><b>前置知识</b> ${a.prereq}</p><p class="evidence-note">约 ${a.minutes} 分钟 · 代码基线 PyTorch 2.5.1 · <a href="#/labs">查看实验验证范围 ↗</a></p></div>`}
function mobileContents(a){return `<details class="mobile-contents"><summary>章节导航与本文目录</summary><a href="#/module/${a.module}">← 返回本模块目录</a>${a.sections.map((s,i)=>`<a href="${articleURL(a.id)}?section=${i+1}">${i+1}. ${s[0]}</a>`).join('')}</details>`}
function courseIntro(){return `<div class="course-intro"><span class="small-badge">系统课程 / 10 章</span><h2>理解机制，完成实验，验证恢复。</h2><p>先建立资源模型，再读懂训练代码，最后将任务扩展到两机四卡。五张架构图和同一份实验程序贯穿全程。</p><div class="course-links"><a class="btn" href="#/article/gpu-cluster">从第一章开始 →</a><a class="btn secondary" href="#/labs">实验包与验证记录 ↗</a></div><small>CPU/Gloo 的实际验证与 GPU/NCCL 的待验范围分别列示。</small></div>`}
function sectionGroup(list){return trainingGroups.map((g,i)=>`<section class="course-group"><div class="group-label">${g}</div>${list.filter(a=>a.group===i).map(chapterLink).join('')}</section>`).join('')}
function simplePage(title,kicker,desc,body){document.title=title+' · CloudInfra Guide';$('#app').innerHTML=`<main id="main" class="container collection" tabindex="-1"><div class="breadcrumb"><a href="#/">知识库</a><span>／ ${title}</span></div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="description">${desc}</p>${body}</main>${footer()}`}
function trackPage(kind){const ai=kind==='ai',list=modules.filter(m=>(ai?aiModules:cloudModules).includes(m.id));simplePage(ai?'AI Infra':'Cloud Infra',ai?'BUILD THE SYSTEMS BEHIND AI':'BUILD A RELIABLE CLOUD FOUNDATION',ai?'从训练执行机制，到 GPU 资源与平台生命周期。':'计算、网络、存储、云原生与可靠性，构成可迁移的工程基础。',`<div class="track-note"><b>${ai?'当前主线：云上训练':'建议起点：一条请求如何经过云系统'}</b><p>${ai?'训练专题已展开为 10 章。推理服务是下一阶段，Agent Infra 将结合 Kairo 单独组织。':'按知识依赖学习，也可以从问题索引进入。SRE 的观测、恢复和成本视角贯穿后续 AI 系统。'}</p><a href="#/roadmap">查看学习依赖 →</a></div><div class="module-grid">${list.map(moduleCard).join('')}</div>${ai?`<section class="planned"><span class="status-pill">规划中</span><h2>推理与模型服务</h2><p>后续按请求生命周期展开：模型加载、KV Cache、批处理与调度、吞吐与延迟、扩缩容、发布与回滚。完成可复现实验后再开放章节。</p></section>`:''}<div class="collection-actions"><a href="#/problems">从问题出发 →</a><a href="#/about">内容质量与建设路线 →</a></div>`)}
function labsPage(){let v=typeof labValidation!=='undefined'?labValidation:null;simplePage('实战实验室','RUN · OBSERVE · RECOVER','用可下载的代码，把机制、指标和恢复能力连起来。',`<section class="lab-hero"><div><span class="small-badge">LAB 01 / DISTRIBUTED TRAINING</span><h2>从 CPU 两进程到两机四卡</h2><p>一份 DDP 程序，覆盖数据分片、梯度累积、混合精度和 epoch 边界恢复。无需下载外部数据集。</p><div class="buttons"><a class="btn" href="labs/cloud-training-ddp.zip" download>下载实验包 ↓</a><a class="btn secondary" href="#/article/multinode-lab">打开操作手册 →</a></div></div><div class="lab-spec"><span>PYTORCH <b>2.5.1</b></span><span>PYTHON <b>3.10—3.12</b></span><span>GPU 拓扑 <b>2 节点 × 2 卡</b></span><span>恢复边界 <b>固定规模 / epoch</b></span></div></section><section class="quality-section"><h2>验证记录</h2><p>结果只对记录的环境和配置成立；GPU 结果不会由 CPU 结果推定。</p>${trainingTable(['验证项','状态','范围'],[['CPU/Gloo 两进程训练',v?.cpu_ddp==='passed'?'已执行通过':'待执行','本机合成数据与 FP32'],['连续训练与恢复对照',v?.resume==='passed'?'已执行通过':'待执行','模型、优化器、scaler、RNG 与进度的完整状态比较'],['错误配置拒绝',v?.negative==='passed'?'已执行通过':'待执行','累积步数不整除、不兼容恢复'],['两端启动脚本的本机模拟',v?.simulated_two_agents==='passed'?'已执行通过':'待执行','同一主机、两个启动代理、4 个 CPU rank；不验证物理网络'],['真实两机四卡 / NCCL','待 GPU 集群验证','本文提供运行手册，未声称完成实测'],['GPU 混合精度 / Kubernetes','待目标环境验证','示例与验收设计，不是已验证部署']])}${v?`<p class="evidence-note">实测环境：${escapeHTML(v.environment)} · ${escapeHTML(v.date)}。<a href="labs/ddp/validation.json" target="_blank" rel="noopener">查看机器可读记录 ↗</a></p>`:''}</section><div class="lab-route">${[['01','读懂程序','ddp-code'],['02','启动两机四卡','multinode-lab'],['03','验证断点恢复','checkpoint-recovery'],['04','建立性能实验','training-performance']].map(([n,t,id])=>`<a href="${articleURL(id)}"><small>STEP ${n}</small><strong>${t} →</strong></a>`).join('')}</div><section class="quality-section"><h2>下载包包含什么</h2><p>训练程序、环境检查、两节点启动器、检查点比较器、中文运行手册和验证记录。完整源码在章节内也可展开、复制。</p><p>本实验使用小型合成分类任务，用于检验工程流程；它不能替代大模型的性能、收敛质量或生产可靠性验证。</p></section>`)}
const problemItems=[
['训练 OOM，增加 GPU 仍没解决','先算状态与激活预算，再判断复制还是分片。','gpu-memory','显存'],
['卡都很忙，但训练不快','核对有效吞吐、比较口径和关键路径。','training-performance','性能'],
['多机启动等待或中途超时','先找最早异常，再区分会合与数据通信。','training-communication','网络'],
['GPU 经常等待数据','用设备输入、合成输入、真实输入做三组对照。','data-pipeline','数据'],
['保存了检查点，却不能继续','核对恢复状态、world size、进度与数据顺序。','checkpoint-recovery','恢复'],
['两个 Pod 没组成一个训练作业','检查 rank、会合与协同生命周期。','kubernetes-training','调度'],
['在线系统异常，从哪里排查','围绕影响、时间线和证据建立假设。','incident','SRE']
];
function problemsPage(){simplePage('问题索引','START WITH A SYMPTOM','从当前现象找到需要理解的机制与下一步实验。',`<div class="problem-list">${problemItems.map(([t,d,id,tag])=>`<a href="${articleURL(id)}"><span class="tag">${tag}</span><div><h2>${t}</h2><p>${d}</p></div><b>↗</b></a>`).join('')}</div><p class="evidence-note">现象只用于选择排查入口，不是预先给出的根因判断。</p>`)}
function editorialPage(){simplePage('内容质量与建设路线','AN ENGINEERING KNOWLEDGE BASE','面向有后端、运维或 SRE 基础，希望系统进入云与 AI 基础设施的工程师。',`
<div class="scope-diagram"><div><small>共享底座</small><strong>计算 · 网络 · 存储 · 云原生</strong></div><span>↓</span><div><small>主站的两条主线</small><strong>Cloud Infra ↔ AI Infra</strong><p>SRE、可观测性、恢复、安全与成本贯穿其中。</p></div><span>↗</span><div class="scope-companion"><small>独立系列规划</small><strong>Agent Infra × Kairo</strong><p>以运行时、工具执行、持久化、恢复和评估为核心。</p></div></div>
<section class="quality-section"><h2>每篇深入教程的交付标准</h2>${trainingTable(['标准','读者能检查的证据'],[['问题明确','解释要解决什么，列出前置知识与学习出口'],['机制完整','说明因果关系、适用条件、失败方式和替代方案'],['图文一致','架构图标明控制流、数据流和边界，对应正文术语'],['代码可用','完整实验与示意片段区分，版本、依赖和命令齐全'],['结果可验','预期输出、通过条件、反例和实测环境可追踪'],['来源可靠','优先官方资料；外部事实与本站建议区分'],['持续维护','更新环境后重跑相关验证，保留旧结论的适用范围']])}</section>
<section class="quality-section"><h2>明确内容成熟度</h2><p><b>基础导读：</b>建立概念与依赖关系，不承诺完整部署。<b>深入教程：</b>解释机制、权衡与故障。<b>已执行实验：</b>附环境与结果。<b>待环境验证：</b>提供步骤与验收，不标注实测成功。<b>规划中：</b>不进入已完成章节统计。</p><p>当前共有 ${modules.length} 个模块、${articles.length} 篇内容；其中云上训练为 10 章深入专题，其余保留为基础导读。已有文章不因篇幅增加就自动升级为已验证教程。</p></section>
<section class="quality-section"><h2>按质量门槛推进，而不是按文章数量推进</h2><ol class="quality-roadmap"><li><strong>第一阶段 · 训练样板</strong><p>形成章节、图、实验、恢复对照和证据记录的完整链路。GPU 实测单独验收。</p></li><li><strong>第二阶段 · 补齐共享底座</strong><p>深化网络、存储、Kubernetes、SRE；每个专题至少完成一个可复现实验和一个故障练习。</p></li><li><strong>第三阶段 · 推理与平台</strong><p>从模型服务的延迟、吞吐、调度和发布展开，建立训练与推理的完整 AI Infra 视角。</p></li><li><strong>独立推进 · Agent Infra × Kairo</strong><p>按“真实问题 → 通用机制 → 实现选择 → 故障实验 → 证据”组织。框架说明与通用教程分开，文档目标与已验证能力分开；后续发布前整理可公开案例。</p></li></ol></section>
<section class="quality-section"><h2>阅读与结构</h2><p>学习路线回答“先学什么”，知识目录回答“系统有哪些部分”，实验室回答“怎样验证”，问题索引回答“现在该查什么”。搜索覆盖标题、标签与正文；阅读进度只保存在当前浏览器。</p><p>导航组织参考 <a href="https://caomaolufei.github.io/AIInfraGuide/" target="_blank" rel="noopener">AIInfraGuide ↗</a> 的章节树、正文与页内目录。本站内容和架构图为原创。</p></section>`)}

